// TestInsertWatchedIdempotent pins the completion-ledger contract: one row
// per item forever — a repeat write and a rewatch (a later completed_at for
// a known item) are PK no-ops that keep the FIRST completed_at; a film item
// (empty series path) persists NULL; distinct items are distinct rows.
func TestInsertWatchedIdempotent(t *testing.T) {
	t.Run("rewatch_and_repeat_are_no_ops", func(t *testing.T) {
		s := openStore(t)
		ctx := context.Background()
		first := time.Date(2026, 11, 1, 12, 0, 0, 0, time.UTC)
		rewatch := first.Add(48 * time.Hour)

		if err := s.InsertWatched(ctx, "it_1", 1, "serials/attack", first, access.System()); err != nil {
			t.Fatalf("first insert: %v", err)
		}
		if err := s.InsertWatched(ctx, "it_1", 1, "serials/attack", rewatch, access.System()); err != nil {
			t.Fatalf("rewatch insert: %v", err)
		}
		if n := watchedRowCount(t, s, "it_1"); n != 1 {
			t.Fatalf("rows for it_1 = %d, want 1 (rewatch must not double-count)", n)
		}
		gotCompleted, _, gotSeries := watchedRow(t, s, "it_1")
		if want := formatTime(first); gotCompleted != want {
			t.Fatalf("completed_at = %q, want first completion %q (rewatch keeps the first)", gotCompleted, want)
		}
		if gotSeries != "serials/attack" {
			t.Fatalf("series_relative_path = %q, want %q", gotSeries, "serials/attack")
		}
	})

	t.Run("film_item_persists_null_series", func(t *testing.T) {
		s := openStore(t)
		ctx := context.Background()
		at := time.Date(2026, 11, 1, 20, 0, 0, 0, time.UTC)
		if err := s.InsertWatched(ctx, "film_1", 2, "", at, access.System()); err != nil {
			t.Fatalf("insert film watch: %v", err)
		}
		_, _, series := watchedRow(t, s, "film_1")
		if series != "" {
			t.Fatalf("series_relative_path = %q, want NULL (empty string) for a film item", series)
		}
	})

	t.Run("distinct_items_are_distinct_rows", func(t *testing.T) {
		s := openStore(t)
		ctx := context.Background()
		at := time.Date(2026, 11, 2, 9, 0, 0, 0, time.UTC)
		if err := s.InsertWatched(ctx, "it_a", 1, "serials/attack", at, access.System()); err != nil {
			t.Fatalf("insert it_a: %v", err)
		}
		if err := s.InsertWatched(ctx, "it_b", 1, "serials/attack", at.Add(time.Minute), access.System()); err != nil {
			t.Fatalf("insert it_b: %v", err)
		}
		if n := watchedRowCount(t, s, ""); n != 2 {
			t.Fatalf("table rows = %d, want 2", n)
		}
	})
}

// TestListUnappliedWatched pins the derived-queue read: only applied_at IS
// NULL rows surface, aligned parallel slices in completed_at order, empty
// series path for film rows, empty non-nil when the queue is empty.
func TestListUnappliedWatched(t *testing.T) {
	t.Run("applied_rows_are_consumed", func(t *testing.T) {
		s := openStore(t)
		ctx := context.Background()
		t0 := time.Date(2026, 11, 1, 10, 0, 0, 0, time.UTC)
		t1 := t0.Add(time.Hour)
		t2 := t0.Add(2 * time.Hour)
		if err := s.InsertWatched(ctx, "ep_2", 1, "serials/attack", t1, access.System()); err != nil {
			t.Fatalf("insert ep_2: %v", err)
		}
		if err := s.InsertWatched(ctx, "film_1", 2, "", t0, access.System()); err != nil {
			t.Fatalf("insert film_1: %v", err)
		}
		if err := s.InsertWatched(ctx, "ep_1", 1, "serials/attack", t2, access.System()); err != nil {
			t.Fatalf("insert ep_1: %v", err)
		}
		// One pass with cutoff t0: consumes film_1 only — ep_2 (t1) and ep_1
		// (t2) complete after the cutoff and stay queued.
		if err := s.ApplyTagWeights(ctx, []string{"action"}, t0); err != nil {
			t.Fatalf("apply: %v", err)
		}

		itemIDs, libraryIDs, seriesPaths, completed, err := s.ListUnappliedWatched(ctx)
		if err != nil {
			t.Fatalf("ListUnappliedWatched: %v", err)
		}
		wantIDs := []string{"ep_2", "ep_1"}
		wantPaths := []string{"serials/attack", "serials/attack"}
		wantLibs := []int64{1, 1}
		wantDone := []time.Time{t1, t2}
		if len(itemIDs) != len(wantIDs) {
			t.Fatalf("itemIDs = %v, want %v (applied rows are consumed, the rest queued in order)", itemIDs, wantIDs)
		}
		for i := range wantIDs {
			if itemIDs[i] != wantIDs[i] || libraryIDs[i] != wantLibs[i] ||
				seriesPaths[i] != wantPaths[i] || !completed[i].Equal(wantDone[i]) {
				t.Fatalf("row %d = (%s, %d, %s, %s), want (%s, %d, %s, %s) — slices must stay aligned",
					i, itemIDs[i], libraryIDs[i], seriesPaths[i], completed[i],
					wantIDs[i], wantLibs[i], wantPaths[i], wantDone[i])
			}
		}
	})

	t.Run("film_row_reads_empty_path", func(t *testing.T) {
		s := openStore(t)
		ctx := context.Background()
		t0 := time.Date(2026, 11, 1, 20, 0, 0, 0, time.UTC)
		if err := s.InsertWatched(ctx, "film_1", 2, "", t0, access.System()); err != nil {
			t.Fatalf("insert film_1: %v", err)
		}
		_, _, seriesPaths, _, err := s.ListUnappliedWatched(ctx)
		if err != nil {
			t.Fatalf("ListUnappliedWatched: %v", err)
		}
		if len(seriesPaths) != 1 || seriesPaths[0] != "" {
			t.Fatalf("seriesPaths = %v, want [\"\"] (NULL scans as empty string)", seriesPaths)
		}
	})

	t.Run("ordered_by_completed_at", func(t *testing.T) {
		s := openStore(t)
		ctx := context.Background()
		base := time.Date(2026, 11, 1, 8, 0, 0, 0, time.UTC)
		// Inserted out of order: c_last gets the earliest completion.
		for i, id := range []string{"c_last", "a_first", "b_mid"} {
			at := base.Add(time.Duration(2-i) * time.Minute)
			if err := s.InsertWatched(ctx, id, 1, "serials/x", at, access.System()); err != nil {
				t.Fatalf("insert %s: %v", id, err)
			}
		}
		itemIDs, _, _, _, err := s.ListUnappliedWatched(ctx)
		if err != nil {
			t.Fatalf("ListUnappliedWatched: %v", err)
		}
		want := []string{"b_mid", "a_first", "c_last"}
		for i, id := range want {
			if itemIDs[i] != id {
				t.Fatalf("itemIDs[%d] = %q, want %q (completed_at order)", i, itemIDs[i], id)
			}
		}
	})

	t.Run("empty_queue", func(t *testing.T) {
		s := openStore(t)
		itemIDs, libraryIDs, seriesPaths, completed, err := s.ListUnappliedWatched(context.Background())
		if err != nil {
			t.Fatalf("ListUnappliedWatched: %v", err)
		}
		if itemIDs == nil || libraryIDs == nil || seriesPaths == nil || completed == nil {
			t.Fatal("empty queue must return non-nil slices (the ListLibraries convention)")
		}
		if len(itemIDs)+len(libraryIDs)+len(seriesPaths)+len(completed) != 0 {
			t.Fatalf("want all slices empty, got %d/%d/%d/%d",
				len(itemIDs), len(libraryIDs), len(seriesPaths), len(completed))
		}
	})
}

// TestApplyTagWeightsTransaction pins the one-pass learning contract: the
// weights upsert and the queue stamp commit together in ONE transaction —
// each tag +1 (a shared tag accumulates per element), first sight starts at
// 1, the stamp honors the completed_at cutoff (a later watch stays queued
// for the next pass), a failed pass writes nothing, and an empty tag list
// consumes rows without touching weights.
func TestApplyTagWeightsTransaction(t *testing.T) {
	t.Run("weights_and_stamp_commit_together", func(t *testing.T) {
		s := openStore(t)
		ctx := context.Background()
		t0 := time.Date(2026, 11, 1, 10, 0, 0, 0, time.UTC)
		t1 := t0.Add(time.Hour)
		t2 := t0.Add(2 * time.Hour)
		if err := s.InsertWatched(ctx, "w_1", 1, "serials/attack", t0, access.System()); err != nil {
			t.Fatalf("insert w_1: %v", err)
		}
		if err := s.InsertWatched(ctx, "w_2", 1, "serials/attack", t1, access.System()); err != nil {
			t.Fatalf("insert w_2: %v", err)
		}
		if err := s.InsertWatched(ctx, "w_3", 1, "serials/attack", t2, access.System()); err != nil {
			t.Fatalf("insert w_3: %v", err)
		}

		// Pass 1: cutoff t1 covers w_1 and w_2 only; w_3 lands after the batch.
		if err := s.ApplyTagWeights(ctx, []string{"action", "thriller"}, t1); err != nil {
			t.Fatalf("apply pass 1: %v", err)
		}
		tags, weights, err := s.ListTagWeights(ctx)
		if err != nil {
			t.Fatalf("ListTagWeights: %v", err)
		}
		wantTags := []string{"action", "thriller"}
		wantWeights := []int64{1, 1}
		if len(tags) != len(wantTags) {
			t.Fatalf("tags = %v, want %v (first sight starts at 1)", tags, wantTags)
		}
		for i := range wantTags {
			if tags[i] != wantTags[i] || weights[i] != wantWeights[i] {
				t.Fatalf("row %d = (%s, %d), want (%s, %d)", i, tags[i], weights[i], wantTags[i], wantWeights[i])
			}
		}
		for _, id := range []string{"w_1", "w_2"} {
			if _, applied, _ := watchedRow(t, s, id); applied == "" {
				t.Fatalf("%s must be stamped applied", id)
			}
		}
		if _, applied, _ := watchedRow(t, s, "w_3"); applied != "" {
			t.Fatalf("w_3 completed after the cutoff must stay unapplied, got applied_at=%q", applied)
		}

		// Pass 2: the cutoff now covers w_3; a repeated tag accumulates.
		if err := s.ApplyTagWeights(ctx, []string{"action"}, t2); err != nil {
			t.Fatalf("apply pass 2: %v", err)
		}
		tags, weights, err = s.ListTagWeights(ctx)
		if err != nil {
			t.Fatalf("ListTagWeights pass 2: %v", err)
		}
		if len(tags) != 2 || tags[0] != "action" || weights[0] != 2 || weights[1] != 1 {
			t.Fatalf("tags/weights = %v/%v, want action=2, thriller=1 (per-element accumulation)", tags, weights)
		}
		if _, applied, _ := watchedRow(t, s, "w_3"); applied == "" {
			t.Fatal("w_3 must be stamped by pass 2 (restart-safe resume)")
		}
	})

	t.Run("failed_pass_writes_nothing", func(t *testing.T) {
		// Drop the ledger under an opened store: the stamp then fails AFTER
		// the weight upserts succeeded inside the transaction — the tx
		// contract means the weight writes roll back with it (all-or-nothing).
		s := openStore(t)
		ctx := context.Background()
		if _, err := s.db.ExecContext(ctx, "DROP TABLE watched_items"); err != nil {
			t.Fatalf("drop watched_items: %v", err)
		}
		err := s.ApplyTagWeights(ctx, []string{"action", "thriller"}, time.Now())
		if err == nil {
			t.Fatal("apply against a store without the ledger must fail")
		}
		if n := tagWeightsRowCount(t, s); n != 0 {
			t.Fatalf("tag_weights rows = %d, want 0 (the failed pass must roll back its weight writes)", n)
		}
	})

	t.Run("empty_tags_stamp_without_weights", func(t *testing.T) {
		s := openStore(t)
		ctx := context.Background()
		t0 := time.Date(2026, 11, 1, 10, 0, 0, 0, time.UTC)
		if err := s.InsertWatched(ctx, "film_1", 2, "", t0, access.System()); err != nil {
			t.Fatalf("insert film_1: %v", err)
		}
		if err := s.ApplyTagWeights(ctx, nil, t0); err != nil {
			t.Fatalf("apply with no tags: %v", err)
		}
		if _, applied, _ := watchedRow(t, s, "film_1"); applied == "" {
			t.Fatal("a no-tag watch must still be consumed (honest absence)")
		}
		tags, weights, err := s.ListTagWeights(ctx)
		if err != nil {
			t.Fatalf("ListTagWeights: %v", err)
		}
		if len(tags) != 0 || len(weights) != 0 {
			t.Fatalf("weights touched = %v/%v, want none", tags, weights)
		}
	})
}

// TestListTagWeights pins the affinity read: aligned parallel slices ordered
// by tag, empty non-nil on the zero-interest state.
func TestListTagWeights(t *testing.T) {
	t.Run("ordered_by_tag", func(t *testing.T) {
		s := openStore(t)
		ctx := context.Background()
		t0 := time.Date(2026, 11, 1, 10, 0, 0, 0, time.UTC)
		// Inserted out of tag order; thriller applied twice to pin accumulation.
		if err := s.ApplyTagWeights(ctx, []string{"thriller", "action", "thriller"}, t0); err != nil {
			t.Fatalf("apply: %v", err)
		}
		tags, weights, err := s.ListTagWeights(ctx)
		if err != nil {
			t.Fatalf("ListTagWeights: %v", err)
		}
		if len(tags) != 2 || len(weights) != 2 {
			t.Fatalf("rows = %v/%v, want 2 aligned rows", tags, weights)
		}
		if tags[0] != "action" || weights[0] != 1 {
			t.Fatalf("row 0 = (%s, %d), want (action, 1)", tags[0], weights[0])
		}
		if tags[1] != "thriller" || weights[1] != 2 {
			t.Fatalf("row 1 = (%s, %d), want (thriller, 2)", tags[1], weights[1])
		}
	})

	t.Run("zero_interest_empty_non_nil", func(t *testing.T) {
		s := openStore(t)
		tags, weights, err := s.ListTagWeights(context.Background())
		if err != nil {
			t.Fatalf("ListTagWeights: %v", err)
		}
		if tags == nil || weights == nil {
			t.Fatal("zero-interest state must return non-nil slices (the ListLibraries convention)")
		}
		if len(tags) != 0 || len(weights) != 0 {
			t.Fatalf("want empty slices, got %v/%v", tags, weights)
		}
	})
}
